func TestReproUnbufferedDeadlock(t *testing.T) {
	ch := make(chan string)
	done := make(chan struct{})
	go func() { ch <- "section"; close(done) }()
	select {
	case <-done: t.Fatal("expected deadlock")
	case <-time.After(200 * time.Millisecond):
		t.Log("unbuffered channel send confirmed blocked")
	}
}
